H.background();
const endo = P.endo > 0.5;
const T = Math.max(P.T, 100);
const Tref = 400;
const dH = endo ? 60000 : -60000;
const R = 8.314;
const Kref = 1.0;
const lnK = Math.log(Kref) - (dH / R) * (1 / T - 1 / Tref);
const K = Math.exp(lnK);
const frac = K / (1 + K);
H.text("Le Chatelier + van 't Hoff:  T shifts K", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Endothermic: heating raises K. Exothermic: heating lowers K.", 24, 52, { color: H.colors.sub, size: 13 });
const bx = 120, by = 110, bw = H.W - 240, bh = 40;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 2 });
const split = bx + bw * Math.min(0.97, Math.max(0.03, frac));
H.rect(bx, by, split - bx, bh, { fill: H.colors.accent });
H.rect(split, by, bx + bw - split, bh, { fill: H.colors.warn });
H.text("products", bx + (split - bx) / 2, by + bh / 2, { color: H.colors.bg, size: 12, align: "center", baseline: "middle", weight: 700 });
H.text("reactants", split + (bx + bw - split) / 2, by + bh / 2, { color: H.colors.bg, size: 12, align: "center", baseline: "middle", weight: 700 });
const pulse = 1 + 0.1 * Math.sin(t * 2);
const yA = by + bh + 30;
const nMol = 8;
for (let i = 0; i < nMol; i++) {
  const onProd = (i / nMol) < frac;
  const baseX = onProd ? (bx + 30 + (i * 37) % ((split - bx) || 1)) : (split + 20 + (i * 31) % ((bx + bw - split) || 1));
  const x = Math.min(bx + bw - 10, Math.max(bx + 10, baseX + 8 * Math.sin(t * 1.3 + i)));
  const y = yA + 18 * Math.sin(t * 1.1 + i * 0.7) + (i % 2) * 24;
  H.circle(x, y, 6 * pulse, { fill: onProd ? H.colors.accent : H.colors.warn });
}
H.text("type: " + (endo ? "ENDOTHERMIC (heat is a reactant)" : "EXOTHERMIC (heat is a product)"), 24, H.H - 90, { color: H.colors.violet, size: 13 });
H.text("T = " + T.toFixed(0) + " K", 24, H.H - 66, { color: H.colors.sub, size: 13 });
H.text("K(T) = " + K.toFixed(2) + "   (K=1 at 400 K)", 24, H.H - 44, { color: H.colors.good, size: 14 });
H.text("product fraction = " + (frac * 100).toFixed(0) + "%", 24, H.H - 22, { color: H.colors.accent, size: 13 });
